export type CourseCatalogEntry = (typeof EDITIONS.en)[number];
export function courseCatalogFor(locale: string): CourseCatalogEntry[] {
  return locale === 'tr' ? EDITIONS.tr : locale === 'es' ? EDITIONS.es : EDITIONS.en;
}
